import json,numpy as np
m=json.load(open('/app/runs/left_plate_approach/meta.json'));C=m['cameras']['robot_r1:zed_link:Camera:0'];K=np.array(C['intrinsic_cv']);E=np.array(C['extrinsic_cv']);R=E[:,:3];cw=-R.T@E[:,3];print('cw',cw)
for uv in [(20,180),(40,180),(60,180),(80,180),(100,180),(120,180),(40,200),(60,200),(80,200),(20,160),(80,160)]:
 ray=R.T@np.linalg.inv(K)@np.array([*uv,1]);
 for z in [.9,1.0]:
  lam=(z-cw[2])/ray[2]
  if lam>0: p=cw+lam*ray; print(uv,z,np.round(p,2))
PY

